python - <<'PY'
from __future__ import annotations
import ast
from pathlib import Path
print('=== Python function/class size audit ===')
rows=[]
for path in Path('backend/app').rglob('*.py'):
    try:
        tree=ast.parse(path.read_text())
    except Exception as exc:
        print('PARSE_ERROR', path, exc)
        continue
    for node in ast.walk(tree):
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)) and getattr(node,'end_lineno',None):
            rows.append((node.end_lineno-node.lineno+1, type(node).__name__, str(path), node.name, node.lineno))
for size,kind,path,name,line in sorted(rows, reverse=True)[:50]:
    print(f'{size:4d} {kind:16s} {path}:{line} {name}')
PY

